    for(let i=0;i<cfg.goals.length;i++){if(i===goalIndex)continue;const ring=cfg.goals[i];ctx.strokeStyle=i<goalIndex?'#9ad97666':'#a3df7525';ctx.lineWidth=1;ctx.setLineDash([2,7]);ctx.beginPath();ctx.arc(ring.x,ring.y,ring.r,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=i<goalIndex?'#9ad976':'#66795b';ctx.font='12px monospace';ctx.textAlign='center';ctx.fillText(i<goalIndex?'✓':String(i+1),ring.x,ring.y+4);}
    ctx.fillStyle='#adf2760b';ctx.beginPath();ctx.arc(goal.x,goal.y,goal.r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#a3df75';ctx.lineWidth=1.5;ctx.setLineDash([4,6]);ctx.beginPath();ctx.arc(goal.x,goal.y,goal.r,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);if(hold){ctx.strokeStyle='#d1ff9c';ctx.lineWidth=5;ctx.beginPath();ctx.arc(goal.x,goal.y,goal.r,-Math.PI/2,-Math.PI/2+Math.PI*2*Math.min(1,hold/(goalIndex===cfg.goals.length-1?cfg.hold:1.5)));ctx.stroke();}ctx.textAlign='center';ctx.font='600 11px sans-serif';ctx.fillStyle='#c5e5b3';ctx.fillText(cfg.goals.length>1?`CHECKPOINT ${goalIndex+1} / ${cfg.goals.length}`:'SANCTUARY',goal.x,goal.y-goal.r-20);ctx.font='10px monospace';ctx.fillStyle='#8eaa83';ctx.fillText(`${goal.x}, ${goal.y}`,goal.x,goal.y+goal.r+23);
    for(const o of hazards){ctx.fillStyle='#b25c4a14';ctx.strokeStyle='#c9775b';ctx.lineWidth=1;ctx.beginPath();ctx.arc(o.x,o.y,o.r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.strokeStyle='#d98b6d30';for(let a=0;a<7;a++){ctx.beginPath();ctx.arc(o.x,o.y,o.r*(.2+a*.11),0,Math.PI*2);ctx.stroke();}ctx.fillStyle='#d79070';ctx.textAlign='center';ctx.font='18px sans-serif';ctx.fillText('×',o.x,o.y+5);}
    ctx.strokeStyle='#6dd9c68c';ctx.lineWidth=1;ctx.beginPath();ctx.arc(target.x,target.y,8,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(target.x-14,target.y);ctx.lineTo(target.x-5,target.y);ctx.moveTo(target.x+5,target.y);ctx.lineTo(target.x+14,target.y);ctx.moveTo(target.x,target.y-14);ctx.lineTo(target.x,target.y-5);ctx.moveTo(target.x,target.y+5);ctx.lineTo(target.x,target.y+14);ctx.stroke();
